#!/usr/bin/env bash
# GSZ step142 — Netflix engine STAGE 2 (admin stock, admin-only). New /admin/netflix
# page: screen plans stocked in own inventory (nf_accounts per plan); full-account
# plans show the portal's live free pool + a portal-product picker. New
# routes/adminNetflix.js + view. Migration: nf_accounts.plan_id,
# product_plans.nf_portal_product_id, products.nf_enabled (+ enable Netflix).
# No customer/checkout change. Idempotent; restores on failure. Robust health check.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step142-$TS"; TMP=$(mktemp -d)
PATCHED=(server.js views/admin/_shell_top.ejs)
NEW=(routes/adminNetflix.js views/admin/netflix.ejs)
echo "==> step142: Netflix engine — Stage 2 (admin stock)"
mkdir -p "$BK"; for f in "${PATCHED[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
NEWHAD=()
for f in "${NEW[@]}"; do if [ -f "$GSZ/$f" ]; then NEWHAD+=("$f"); mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; fi; done
echo "    backup: $BK"
restore(){
  echo "!! FAILED — restoring"
  for f in "${PATCHED[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  for f in "${NEW[@]}"; do keep=0; for h in "${NEWHAD[@]:-}"; do [ "$h" = "$f" ] && keep=1; done; if [ "$keep" = "1" ]; then cp "$BK/$f" "$GSZ/$f"; else rm -f "$GSZ/$f"; fi; done
  pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."
}
trap 'restore' ERR
echo "==> writing new files"; mkdir -p "$GSZ/routes" "$GSZ/views/admin"
echo "" | base64 -d > "$GSZ/routes/adminNetflix.js"
echo ""  | base64 -d > "$GSZ/views/admin/netflix.ejs"
echo "" | base64 -d > "$TMP/p.js"
echo ""   | base64 -d > "$TMP/m.js"
echo "==> applying patches"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/routes/adminNetflix.js"; node --check "$GSZ/server.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');['views/admin/netflix.ejs','views/admin/_shell_top.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"
echo "==> migrating db"; ( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/m.js" )
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
echo "==> waiting for app to come up"
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] && echo "    homepage 200: OK (after ${i}s)" || { echo "    homepage $CODE after ${i}s"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step142 OK ✅  Admin → Netflix (/admin/netflix): add screen stock per plan; full-account plans show the portal's free pool. Next: Stage 3 (auto-assign on paid order) + Stage 4 (customer tiered code panel)."
